const input = $input.first().json;
const metrics = input.body?.metrics || input.metrics || {
  storeName: 'Chic Couture India',
  totalRevenue: 245000,
  orderCount: 48,
  codOrdersCount: 32,
  flaggedCodCount: 6,
  lowStockCount: 3,
  ndrPendingCount: 2,
  deliveredCount: 41
};

const prompt = `Synthesize an executive ecommerce daily operational briefing for ${metrics.storeName || 'D2C Merchant'}.
Key 24-hour performance:
- Total Revenue: ₹${metrics.totalRevenue}
- Orders Processed: ${metrics.orderCount} (${metrics.codOrdersCount} COD, ${metrics.flaggedCodCount} high-risk verified)
- Deliveries Completed: ${metrics.deliveredCount}
- Pending Carrier NDRs: ${metrics.ndrPendingCount}
- SKUs at Low Stock: ${metrics.lowStockCount}

Format in 3 structured sections: 1. Highlights & Revenue, 2. Urgent Action Items (NDR & Low Stock), 3. AI Predictive Advice.`;

return {
  json: {
    metrics,
    recipientEmail: input.body?.recipientEmail || 'owner@chiccouture.in',
    prompt
  }
};

