const prep = $('Prepare Report Metrics').first().json;
const groqRes = $input.first().json;

let executiveSummary = '';
try {
  executiveSummary = groqRes.choices?.[0]?.message?.content?.trim() || '';
} catch (e) {
  executiveSummary = 'Daily briefing generated: revenue ₹' + prep.metrics.totalRevenue + ' across ' + prep.metrics.orderCount + ' orders. 3 critical low-stock items require attention.';
}

return {
  json: {
    status: 'REPORT_GENERATED',
    metrics: prep.metrics,
    executiveSummary,
    recipientEmail: prep.recipientEmail,
    generatedAt: new Date().toISOString()
  }
};
